import json,subprocess,base64,time,shutil
p=budget_root/'training/base_generations.jsonl'
assert p.exists() and len(p.read_text().splitlines())==28
assert not (budget_root/'training/latest.json').exists()
assert not json.loads((budget_root/'training/progress.json').read_text()).get('step',0)
if budget_process.poll() is None:
 budget_process.terminate();budget_process.wait(timeout=20)
shutil.copyfile(budget_root/'training.log',budget_root/'training_before_integrity_gate.log')
worker=budget_root/'unsloth_t4_worker.py';worker.write_bytes(base64.b64decode(''))
budget_training_log=(budget_root/'training.log').open('w')
budget_process=subprocess.Popen([str(budget_root/'venv/bin/python'),str(worker),'--train-view',str(budget_root/'sampling/run/training_view.jsonl'),'--view-manifest',str(budget_root/'sampling/run/training_view_manifest.json'),'--eval-fixtures',str(budget_root/'sampling/new_eval_candidates.jsonl'),'--budget-control',str(budget_root/'budget_control.json'),'--out',str(budget_root/'training')],stdout=budget_training_log,stderr=subprocess.STDOUT)
budget_status.update(state='BASE_EVALUATED_EXACT_ROW_HASH_GATE_PENDING_VIEW',worker_pid=budget_process.pid)
(budget_root/'budget_control.json').write_text(json.dumps(budget_status,indent=2))
print(json.dumps({'state':budget_status['state'],'pid':budget_process.pid,'prior_optimizer_updates':0,'base_generations_preserved':28}))
